SELECT id, provider, model, currency, input_price_per_million, cached_input_price_per_million,
       output_price_per_million, cost_multiplier, enabled, updated_by, created_at, updated_at
FROM ai_model_price
WHERE provider = #{provider}
  AND model = #{model}

INSERT INTO ai_model_price (
  provider, model, currency, input_price_per_million, cached_input_price_per_million,
  output_price_per_million, cost_multiplier, enabled, updated_by, created_at, updated_at
)
VALUES (
  #{provider}, #{model}, #{currency}, #{inputPricePerMillion}, #{cachedInputPricePerMillion},
  #{outputPricePerMillion}, #{costMultiplier}, #{enabled}, #{updatedBy}, #{updatedAt}, #{updatedAt}
)
RETURNING id
